(() => {
  "use strict";

  const root = document.documentElement;
  const header = document.querySelector("[data-site-header]");
  const navToggle = document.querySelector("[data-nav-toggle]");
  const navMenu = document.querySelector("[data-nav-menu]");
  const themeButtons = [...document.querySelectorAll("[data-theme-toggle]")];
  const languageButtons = [...document.querySelectorAll("[data-lang-toggle]")];
  const themeMeta = document.querySelector('meta[name="theme-color"]');
  const descriptionMeta = document.querySelector('meta[name="description"]');
  const status = document.querySelector("#page-status");
  const systemTheme = window.matchMedia?.("(prefers-color-scheme: dark)");
  const allowedThemes = new Set(["dark", "light"]);
  const allowedLanguages = new Set(["en", "id"]);
  const htmlKeys = new Set(["hero.title"]);
  const storage = {
    get(key) {
      try {
        return window.localStorage.getItem(key);
      } catch {
        return null;
      }
    },
    set(key, value) {
      try {
        window.localStorage.setItem(key, value);
      } catch {
        return false;
      }
      return true;
    }
  };

  let language = "en";
  let theme = "dark";
  let menuOpen = false;

  const translate = key => i18n[language]?.[key] ?? i18n.en[key] ?? key;

  function announce(message) {
    if (status) status.textContent = message;
  }

  function paintTheme() {
    root.dataset.theme = theme;
    const dark = theme === "dark";
    themeMeta?.setAttribute("content", dark ? "#111a23" : "#eeeae2");
    themeButtons.forEach(button => {
      button.setAttribute("aria-label", translate(dark ? "switch.theme" : "switch.theme") + (dark ? " (light)" : " (dark)"));
      button.setAttribute("title", translate("switch.theme"));
    });
  }

  function paintLanguage() {
    root.lang = language === "id" ? "id" : "en";
    document.querySelectorAll("[data-i18n]").forEach(element => {
      const key = element.dataset.i18n;
      const value = translate(key);
      if (htmlKeys.has(key)) element.innerHTML = value;
      else element.textContent = value;
    });
    document.querySelectorAll("[data-i18n-aria]").forEach(element => {
      const key = element.dataset.i18nAria;
      let label = translate(key);
      if (key === "nav.menu" && menuOpen) label = translate("nav.close");
      element.setAttribute("aria-label", label);
    });
    document.querySelectorAll("[data-lang-label]").forEach(element => {
      element.textContent = language === "id" ? "ID" : "EN";
    });
    languageButtons.forEach(button => {
      button.setAttribute("aria-label", translate("switch.lang"));
      button.setAttribute("title", translate("switch.lang"));
    });
    if (descriptionMeta) descriptionMeta.content = translate("meta.description");
    document.title = translate("meta.title");
    paintTheme();
    if (menuOpen) paintMenu();
  }

  function paintMenu() {
    if (!navToggle || !navMenu) return;
    navToggle.setAttribute("aria-expanded", String(menuOpen));
    navToggle.setAttribute("aria-label", translate(menuOpen ? "nav.close" : "nav.menu"));
    navToggle.title = translate(menuOpen ? "nav.close" : "nav.menu");
    navMenu.hidden = !menuOpen;
  }

  function setMenu(next, restoreFocus = false) {
    if (!navToggle || !navMenu) return;
    menuOpen = Boolean(next);
    paintMenu();
    if (menuOpen) {
      navMenu.querySelector("a")?.focus();
    } else if (restoreFocus) {
      navToggle.focus();
    }
  }

  function updateHeader() {
    header?.classList.toggle("is-scrolled", window.scrollY > 12);
  }

  function bootReveals() {
    const loadItems = root.querySelectorAll(".page-load");
    requestAnimationFrame(() => loadItems.forEach(item => item.classList.add("is-loaded")));

    const revealItems = root.querySelectorAll(".reveal");
    if (!("IntersectionObserver" in window)) {
      revealItems.forEach(item => item.classList.add("is-visible"));
      return;
    }
    const observer = new IntersectionObserver(entries => {
      entries.forEach(entry => {
        if (!entry.isIntersecting) return;
        entry.target.classList.add("is-visible");
        observer.unobserve(entry.target);
      });
    }, { rootMargin: "0px 0px -8% 0px", threshold: 0.08 });
    revealItems.forEach(item => observer.observe(item));
  }

  function init() {
    root.classList.add("js");

    const savedLanguage = storage.get("ai.lang");
    const browserLanguage = (navigator.language || "en").toLowerCase();
    language = allowedLanguages.has(savedLanguage) ? savedLanguage : browserLanguage.startsWith("id") ? "id" : "en";

    const savedTheme = storage.get("ai.theme");
    theme = allowedThemes.has(savedTheme) ? savedTheme : systemTheme?.matches ? "dark" : "light";

    paintLanguage();
    paintMenu();
    updateHeader();
    bootReveals();

    themeButtons.forEach(button => {
      button.addEventListener("click", () => {
        theme = theme === "dark" ? "light" : "dark";
        storage.set("ai.theme", theme);
        paintTheme();
        announce(translate(theme === "dark" ? "switch.theme" : "switch.theme"));
      });
    });

    languageButtons.forEach(button => {
      button.addEventListener("click", () => {
        language = language === "en" ? "id" : "en";
        storage.set("ai.lang", language);
        paintLanguage();
        announce(language === "id" ? "Bahasa Indonesia dipilih" : "English selected");
      });
    });

    navToggle?.addEventListener("click", () => setMenu(!menuOpen));
    navMenu?.querySelectorAll("a").forEach(link => link.addEventListener("click", () => setMenu(false)));
    document.addEventListener("keydown", event => {
      if (event.key === "Escape" && menuOpen) {
        setMenu(false, true);
      }
    });
    document.addEventListener("click", event => {
      if (menuOpen && !header?.contains(event.target)) setMenu(false);
    });
    window.addEventListener("scroll", updateHeader, { passive: true });
    window.addEventListener("pagehide", () => setMenu(false));
    window.matchMedia?.("(min-width: 64rem)").addEventListener?.("change", event => {
      if (event.matches) setMenu(false);
    });
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", init, { once: true });
  } else {
    init();
  }
})();
